namespace {
void Require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}
std::vector<std::uint8_t> Probe(std::size_t size) {
    std::vector<std::uint8_t> result(size);
    std::uint32_t state = 0xC0DEC0DEU;
    for (std::size_t i = 0; i < size; ++i) {
        state ^= state << 13U; state ^= state >> 17U; state ^= state << 5U;
        result[i] = static_cast<std::uint8_t>(state & 127U);
        if (i % 8192U >= 4096U) result[i] = static_cast<std::uint8_t>((i / 8192U) & 127U);
    }
    return result;
}
std::uint32_t ReadU32(const std::vector<std::uint8_t>& bytes, std::size_t offset) {
    return static_cast<std::uint32_t>(bytes[offset])
        | (static_cast<std::uint32_t>(bytes[offset + 1]) << 8U)
        | (static_cast<std::uint32_t>(bytes[offset + 2]) << 16U)
        | (static_cast<std::uint32_t>(bytes[offset + 3]) << 24U);
}
void PutU32(std::vector<std::uint8_t>& bytes, std::size_t offset, std::uint32_t value) {
    for (unsigned i = 0; i != 4; ++i) bytes[offset + i] = static_cast<std::uint8_t>(value >> (i * 8U));
}
}

